"use strict";
window.CampaignRearView=(()=>{
 const ns='http://www.w3.org/2000/svg',node=(tag,attrs={},text)=>{const n=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;return n;};
 function network(number){const saved=CampaignGeographicStore.read(localStorage,number),profile=CampaignSupplySpatial.profile([number]),current=profile.rear,previous=saved?.operation.rearSupply?.network;return{saved,route:previous?.version===current.version?previous:current};}
 function card(host,number,label,info){host.querySelector('.supply-map-card')?.remove();const box=document.createElement('aside');box.className='supply-map-card';box.setAttribute('aria-label','Rear supply information');const close=document.createElement('button');close.textContent='Close';close.onclick=()=>box.remove();box.append(close);for(const[tag,text]of [['h3',label],['p',info.route.available===false?'Isolated force: no established rear supply corridor':info.route.hubName+' to forward depot'],['p',info.route.km.toFixed(1)+' km | '+info.route.travelMinutes+' min travel + 30 min receipt'],['p',info.saved?.operation.rearSupply?'Convoy: '+info.saved.operation.rearSupply.status+' | Campaign '+NormandyCommand.clock(info.saved.operation.time):'Route preview. Enable rear-area supply before issuing orders.'],['p',info.route.provenance]]){const n=document.createElement(tag);n.textContent=text;box.append(n);}const go=document.createElement('button');go.textContent='Open command decisions';go.onclick=()=>CampaignNavigation.open(number);box.append(go);host.append(box);}
 function draw(map,layer,scale,number){if(!number)return;const info=network(number);toolbar(map,number,info);const route=info.route,points=route.points.map(CampaignGeography.atlas),g=node('g',{'data-rear-route':route.id});
  if(route.available!==false)g.append(node('polyline',{points:points.map(p=>p.x+','+p.y).join(' '),fill:'none',stroke:'#fffdf5','stroke-width':scale*7}),node('polyline',{points:points.map(p=>p.x+','+p.y).join(' '),fill:'none',stroke:'#805728','stroke-width':scale*3,'stroke-dasharray':scale*8+' '+scale*4}));
  const entries=[{id:'rear',label:route.hubName,text:'BASE',position:points[0]},{id:'entry',label:'Situation supply entry',text:'IN',position:CampaignGeography.atlas(route.entryPosition)},{id:'forward',label:'Forward depot',text:'DEP',position:points.at(-1)}];
  if(route.available!==false&&info.saved?.operation.rearSupply){const p=CampaignSupplySpatial.point(route.points,CampaignRearSupply.progress(info.saved.operation));entries.push({id:'convoy',label:'Rear supply convoy',text:'TRK',position:CampaignGeography.atlas(p)});}
  for(const e of entries){if(route.available===false&&e.id!=='forward')continue;if(e.id==='forward'&&layer.querySelector('[data-continental-source]'))continue;const marker=node('g',{transform:`translate(${e.position.x} ${e.position.y}) scale(${scale})`,role:'button',tabindex:0,'aria-label':e.label,'data-rear-node':e.id});marker.append(node('rect',{x:-22,y:e.id==='convoy'?15:-12,width:44,height:24,rx:3,fill:'#805728',stroke:'white','stroke-width':2}),node('text',{x:0,y:e.id==='convoy'?31:4,'text-anchor':'middle','font-size':11,fill:'white'},e.text));marker.onclick=event=>{event?.stopPropagation();card(map.parentElement,number,e.label,info);};marker.onkeydown=event=>{if(['Enter',' '].includes(event.key)){event.preventDefault();marker.onclick();}};g.append(marker);}
  layer.append(g);
 }
 function toolbar(map,number,info){
  const host=map.parentElement;host.querySelector('.rear-network-toolbar')?.remove();if(!new URLSearchParams(location.search).has('supplySituation'))return;
  const bar=document.createElement('section');bar.className='rear-network-toolbar';bar.setAttribute('aria-label','Rear supply timeline');const s=info.saved?.operation;
  const time=document.createElement('strong');time.textContent=s?'Campaign '+NormandyCommand.clock(s.time)+' | '+(s.rearSupply?'Rear convoy '+s.rearSupply.status:'Route preview'):'Rear supply route preview';bar.append(time);
  if(s?.queue.length){const next=Math.min(...s.queue.map(e=>e.at)),button=document.createElement('button');button.textContent='Advance to '+NormandyCommand.clock(next);button.title=s.queue.filter(e=>e.at===next).map(e=>e.kind.replace('logistics:rear-','Rear convoy ').replace('logistics:','')).join(', ');button.onclick=()=>{try{CampaignRearController.advance(number,info.saved);}catch(e){const message=document.createElement('p');message.setAttribute('role','alert');message.textContent=e.message;bar.append(message);}};bar.append(button);}
  const go=document.createElement('button');go.textContent='Command decisions';go.onclick=()=>CampaignNavigation.open(number);bar.append(go);host.append(bar);
 }
 function focus(map,number){const {route}=network(number),p=route.points.map(CampaignGeography.atlas),xs=p.map(p=>p.x),ys=p.map(p=>p.y),w=Math.max(10,Math.max(...xs)-Math.min(...xs)),h=Math.max(10,Math.max(...ys)-Math.min(...ys)),box=[Math.min(...xs)-w*.2,Math.min(...ys)-h*.2,w*1.4,h*1.4];view=box;renderView();document.getElementById('mapHeading').textContent='Rear supply network';document.getElementById('breadcrumb').textContent=route.hubName+' / forward depot / Situation';document.getElementById('viewLevel').textContent='CONTINENTAL SUPPLY NETWORK';}
 return{draw,focus};
})();
